import { candidateQuestionProjection, companyQuestionProjection, questionAnswerDraft, questionInternalDraft, QUESTION_ANSWER_STATUSES } from './question-tracker.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function publicAnswerView(answer) {
  if(!answer)return '<span class="pill warning">公開回答はまだありません</span><p class="small">回答の公開を待つか、この時点の内容で話すかは自分で選べます。</p>';
  return `<div class="public-answer"><span class="pill ${answer.status==='answered'?'':'warning'}">${QUESTION_ANSWER_STATUSES[answer.status]}</span>${answer.text?`<p>${esc(answer.text)}</p>`:''}${answer.reason?`<p class="small">状況・理由：${esc(answer.reason)}</p>`:''}${answer.status==='checking'?`<p class="small">確認の目安：${esc(answer.eta||'未定')}（確約ではありません）</p>`:''}<span class="small">提出 v${answer.sourceVersion} に対する公開回答</span></div>`;
}
export function answerPreviewView(preview) {
  return `<p class="small">この経験の提出 v${preview.sourceVersion} に対する回答です。</p><blockquote>${esc(preview.questionText)}</blockquote>${publicAnswerView(preview)}<p class="small">ここに表示した範囲だけを候補者のデモ画面へ公開します。社内の確認先・内部メモは含めません。実際のメール・通知は送信しません。</p>`;
}
export function candidateQuestionsView(state) {
  const questions=candidateQuestionProjection(state),shared=questions.filter(q=>q.visibility==='shared_with_company');
  return `<section class="card question-tracker"><span class="eyebrow">あなたからの質問、その返事</span><h2>気になることを、残しておく。</h2><p class="small">灯りワークスへの質問です。経験ごとに分けて保存します。共有済み ${shared.length} 件・下書き ${questions.length-shared.length} 件。</p>${questions.map(q=>`<article class="question-card"><span class="pill ${q.visibility==='draft'?'quiet':''}">${q.visibility==='draft'?'下書き・会社には未共有':'会社へ共有済み'}</span><h3>${esc(q.text)}</h3>${q.visibility==='draft'?`<div class="actions stack"><button class="button" data-action="share-question" data-question-id="${esc(q.questionId)}">この質問を確認して共有</button><button class="text-link" data-action="cancel-question-draft" data-question-id="${esc(q.questionId)}">質問下書きを取り消す</button></div>`:`${publicAnswerView(q.answer)}${q.previousAnswer?`<details class="old-answer"><summary>以前の提出版への回答を見る（v${q.previousAnswer.sourceVersion}）</summary><p class="small">質問や経験が訂正される前の回答です。最新の回答とは分けて表示しています。</p><blockquote>${esc(q.previousAnswer.questionText)}</blockquote>${publicAnswerView(q.previousAnswer)}</details>`:''}`}</article>`).join('')}<section class="question-composer"><label class="field" for="new-question"><span>質問をもう一つ追加する（架空データ）</span><textarea id="new-question" data-question-composer="true" rows="3" maxlength="4000">${esc(state.questionComposer)}</textarea></label><button class="button secondary full" data-action="add-question-draft">質問を下書きに保存</button><p class="small">下書き保存だけでは会社に共有されません。共有後の本文は記録として残します。補足は新しい質問として追加できます。</p></section></section>`;
}
export function companyQuestionsView(state) {
  const questions=companyQuestionProjection(state),pending=questions.filter(q=>!q.answer||q.answer.status!=='answered').length;
  return `<section class="card company-question-tracker"><span class="eyebrow">この経験の質問トラッカー</span><h2>質問を見落とさず、返事を届ける。</h2><p class="small">会社へ共有された質問 ${questions.length} 件・回答あり以外 ${pending} 件。候補者の質問下書きは表示していません。</p>${questions.map((q,i)=>{
    const draft=questionAnswerDraft(state,q.questionId),internal=questionInternalDraft(state,q.questionId),saved=state.questionInternals[q.questionId];
    return `<details class="question-admin" ${(state.openQuestionId?state.openQuestionId===q.questionId:i===0)?'open':''}><summary>${esc(q.text)}<span class="pill ${q.answer?.status==='answered'?'':'warning'}">候補者向け：${q.answer?QUESTION_ANSWER_STATUSES[q.answer.status]:'未公開'}</span></summary><p class="small">提出 v${q.sourceVersion} に対する質問</p><section class="question-internal"><h3>社内の確認用</h3><label class="field" for="${q.questionId}-checker"><span>確認先（任意・架空の役割や名前）</span><input id="${q.questionId}-checker" data-q-internal="checkWith" data-question-id="${q.questionId}" maxlength="120" value="${esc(internal.checkWith)}"></label><label class="field" for="${q.questionId}-internal"><span>内部の確認メモ（候補者向け回答とは別に保存）</span><textarea id="${q.questionId}-internal" data-q-internal="internalNote" data-question-id="${q.questionId}" rows="3" maxlength="4000">${esc(internal.internalNote)}</textarea></label><button class="button secondary full" data-action="save-question-internal" data-question-id="${q.questionId}">内部メモを保存</button><p class="small">${saved?`内部メモ保存済み（提出 v${esc(saved.sourceVersion)} 時点）。`:'内部メモはまだ保存していません。'}確認先と内部メモは公開プレビューにも候補者向けの出力にも含めません。</p></section><section class="question-public-editor"><h3>候補者へ公開する回答の下書き</h3><span class="pill quiet">現在の候補者向け表示：${q.answer?QUESTION_ANSWER_STATUSES[q.answer.status]:'未公開'}</span><label class="field" for="${q.questionId}-status"><span>公開する回答の状態</span><select id="${q.questionId}-status" data-q-answer="status" data-question-id="${q.questionId}">${Object.entries(QUESTION_ANSWER_STATUSES).map(([key,label])=>`<option value="${key}" ${draft.status===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="field" for="${q.questionId}-text"><span>公開する回答（回答ありの場合は必須）</span><textarea id="${q.questionId}-text" data-q-answer="text" data-question-id="${q.questionId}" rows="4" maxlength="4000">${esc(draft.text)}</textarea></label><button class="text-link" data-action="question-answer-sample" data-question-id="${q.questionId}">架空の回答例を入れる</button><label class="field" for="${q.questionId}-reason"><span>公開する状況・理由（回答あり以外は必須）</span><textarea id="${q.questionId}-reason" data-q-answer="reason" data-question-id="${q.questionId}" rows="3" maxlength="4000">${esc(draft.reason)}</textarea></label><label class="field" for="${q.questionId}-eta"><span>公開する確認目安（任意・期限未定も可）</span><input id="${q.questionId}-eta" data-q-answer="eta" data-question-id="${q.questionId}" type="date" value="${esc(draft.eta)}"></label><button class="button full" data-action="preview-question-answer" data-question-id="${q.questionId}">候補者に見える回答をプレビュー</button><p class="small">入力中は未公開です。プレビュー後に、公開ボタンを明示的に押して反映します。</p>${q.previousAnswer?'<p class="warning-text">以前の提出版への公開回答は履歴として保持しています。最新の質問・経験と照合して回答してください。</p>':''}</section></details>`;
  }).join('')}</section>`;
}
